from django.db import migrations, models

# The list grouped itself by the theme text before a type field existed, and the rows the site
# was built from all used one of these four headings. Reading them once here means a paper does
# not fall back to "Original research" just because the field is new.
KIND_BY_TAG = {
    "original research": "research",
    "reviews and book chapters": "review",
    "case reports": "case",
    "conference abstracts and editorials": "abstract",
}


def copy_tag_into_kind( apps, *args ):
    for entry in apps.get_model( "cms", "Publication" ).objects.all():
        kind = KIND_BY_TAG.get( entry.tag.strip().lower() )
        if kind and entry.kind != kind:
            entry.kind = kind
            entry.save( update_fields = [ "kind" ] )


